#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Alpha-Bot 离线安装脚本 -- 运行: python install_bots.py"""
import base64, os

WHALE = ''
BAT   = ''
AUTO  = ''

def install(name, b64):
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), name)
    with open(path, "wb") as f:
        f.write(base64.b64decode(b64))
    print("  已创建: " + name)

print("Alpha-Bot 离线安装")
print("=" * 40)
install("whale_memecoin_bot.py", WHALE)
install("start_bots.bat",        BAT)
install("auto_trader.py",        AUTO)
print()
print("安装完成！")
print("  双击 start_bots.bat  --- 同时启动两个机器人")
print("  python auto_trader.py         --- 只运行 BTC 交易机器人")
print("  python whale_memecoin_bot.py  --- 只运行鲸鱼追踪机器人")
